import { useState } from 'react';
import Constellation from '../components/Constellation';
import ProjectCard from '../components/ProjectCard';
import SocialIcons from '../components/SocialIcons';
import { HERO_CONSTELLATIONS } from '../data/constellations';
import { projects } from '../data/projects';
import './WorkPage.css';

const HERO_LAYOUT = {
  pisces: { className: 'work-hero__constellation--pisces' },
  delphinus: { className: 'work-hero__constellation--delphinus' },
  aquila: { className: 'work-hero__constellation--aquila' },
};

export default function WorkPage() {
  const [heroHovered, setHeroHovered] = useState(false);

  return (
    <div className="work-page">
      <section
        className="work-hero"
        onMouseEnter={() => setHeroHovered(true)}
        onMouseLeave={() => setHeroHovered(false)}
      >
        <div className="work-hero__text">
          <h1 className="work-hero__title">DHIKSHIKA CHERIVIRALA</h1>
          <p className="work-hero__subtitle">
            Designing, developing, and delivering solutions that make an impact.
          </p>
          <p className="work-hero__bio">
            A CS student @ Cornell exploring the intersection of software
            engineering, product design, and social impact. ✦
          </p>
          <SocialIcons />
        </div>
        <div className="work-hero__constellations" aria-hidden="true">
          {HERO_CONSTELLATIONS.map((key) => (
            <Constellation
              key={key}
              variant={key}
              active={heroHovered}
              showLabel
              className={HERO_LAYOUT[key].className}
            />
          ))}
        </div>
      </section>

      <section className="work-grid" aria-label="Projects">
        {projects.map((project) => (
          <ProjectCard key={project.slug} project={project} />
        ))}
      </section>
    </div>
  );
}
